import { Accessor, Component, Show } from "solid-js";

import { Layout } from "#core/ui/utilities/utilities-layout.js";
import { MetalCardFrame } from "#core/ui-next/components/card-frame.jsx";
import type { DraggableProps } from "#core/ui-next/components/drag-and-drop.jsx";
import { L10n } from "#core/ui-next/components/l10n.jsx";
import { NavHelp } from "#core/ui-next/components/nav-help.jsx";
import { IsControllerActive } from "#core/ui-next/services/input.js";
import { isMobile } from "#core/ui-next/services/view-experience.js";
import { useIsSmallScreen } from "#core/ui-next/utilities/layout-utilities.js";

export interface DedicationCardProps extends DraggableProps {
	id: string;
	title?: string;
	description: string;
	class?: string;
	contentClass?: string;
	icon?: string;
	background?: string;
	navTrayText?: () => string;
	onDedicationActivate?: () => void;
	onHover?: () => void;
	onDehover?: () => void;
	isDisplayOnly?: boolean; // Deactivate all interactivity, just for showing
	tabIndex?: number;
}

export interface DedicationCardContentProps extends DedicationCardProps {
	isHover?: Accessor<boolean>;
	isDragging?: Accessor<boolean>;
	onHover?: () => void;
	onDehover?: () => void;
}

export const DedicationCardContents: Component<DedicationCardContentProps> = (props: DedicationCardContentProps) => {
	const isSmallScreen = useIsSmallScreen();
	return (
		<div
			class={`relative flex justify-center max-w-full ${props.contentClass || ""}`}
			classList={{
				"w-72 min-h-32": !isMobile(),
				"w-96 min-h-36": isMobile() && isSmallScreen(),
			}}
			style={
				isMobile() && !isSmallScreen()
					? {
							width: `${Layout.pixelsToScreenPixels(412)}px`,
							"min-height": `${Layout.pixelsToScreenPixels(182)}px`,
						}
					: {}
			}
		>
			{/* Content is not inside the MetalFrame because we want the background gradient to stay behind the frame */}
			<div
				class="relative overflow-hidden w-full min-h-32 p-3 flex flex-col items-center"
				classList={{ "text-xs": !isMobile(), "text-sm": isMobile() }}
			>
				<div
					class="absolute inset-0"
					style={{
						"background-image": props.background || "",
						filter: props.isHover?.() || props.isDragging?.() ? "brightness(1.5)" : "brightness(1.0)",
					}}
				/>
				<Show when={props.title != undefined}>
					<div class="relative font-title text-center uppercase text-secondary mb-1">
						<L10n.Stylize text={props.title || ""} />
					</div>
				</Show>
				<div class="flex relative flex-auto items-center font-fit-shrink text-center overflow-hidden">
					<Show
						when={IsControllerActive() || !props.isDisplayOnly}
						fallback={<L10n.Stylize text={props.description} />}
					>
						<L10n.Stylize
							text={props.description}
							disableTooltips
							class={`${!props.isDisplayOnly ? "dedication-card-no-tooltip" : ""}`}
						/>
					</Show>
				</div>
			</div>
			<MetalCardFrame
				onMouseEnter={props.isDisplayOnly ? undefined : props.onHover}
				onMouseLeave={props.isDisplayOnly ? undefined : props.onDehover}
				class={`absolute -inset-1 flex justify-center items-center relative ${props.isDisplayOnly ? "pointer-events-none" : ""}`}
			>
				<div
					class="absolute inset-0 metal-card-frame-bg-hover"
					classList={{
						invisible: !(props.isHover?.() || props.isDragging?.()),
					}}
				/>
			</MetalCardFrame>
			<Show when={props.icon != undefined}>
				<div
					class="size-8 absolute bg-contain bg-center bg-no-repeat"
					style={{ "background-image": props.icon || "", top: "-1rem" }}
				/>
			</Show>
			<Show when={props.isHover?.()}>
				<NavHelp class="absolute -top-5 translate-x-full" />
			</Show>
		</div>
	);
};
